package com.example.validation;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;

import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.util.Map;
import java.util.HashMap;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/documents")
public class DocumentValidationService {

    // Pattern to validate document reference codes
    // Format: alphanumeric groups separated by dashes, ending with optional qualifier
    private static final Pattern DOC_REFERENCE_PATTERN = Pattern.compile(
        "^([a-zA-Z0-9]+[-])*[a-zA-Z0-9]+([.][a-zA-Z]{2,})*$"
    );

    // Pattern to validate structured comment fields
    private static final Pattern COMMENT_PATTERN = Pattern.compile(
        "^(([a-z]+)+\\.)+[A-Z]([a-z]+)+$"
    );

    // Email validation pattern (intentionally complex for "thoroughness")
    private static final Pattern EMAIL_PATTERN = Pattern.compile(
        "^([a-zA-Z0-9])(([\\-.]|[_]+)?([a-zA-Z0-9]+))*(@){1}[a-z0-9]+[.]{1}(([a-z]{2,3})|([a-z]{2,3}[.]{1}[a-z]{2,3}))$"
    );

    @PostMapping("/validate")
    public ResponseEntity<Map<String, Object>> validateDocument(
            @RequestBody DocumentRequest request) {

        Map<String, Object> response = new HashMap<>();
        Map<String, String> errors = new HashMap<>();

        // Validate document reference
        if (request.getDocumentRef() != null && !request.getDocumentRef().isEmpty()) {
            Matcher refMatcher = DOC_REFERENCE_PATTERN.matcher(request.getDocumentRef());
            if (!refMatcher.matches()) {
                errors.put("documentRef", "Invalid document reference format");
            }
        }

        // Validate comment field
        if (request.getComment() != null && !request.getComment().isEmpty()) {
            Matcher commentMatcher = COMMENT_PATTERN.matcher(request.getComment());
            if (!commentMatcher.matches()) {
                errors.put("comment", "Invalid comment format");
            }
        }

        // Validate submitter email
        if (request.getSubmitterEmail() != null && !request.getSubmitterEmail().isEmpty()) {
            Matcher emailMatcher = EMAIL_PATTERN.matcher(request.getSubmitterEmail());
            if (!emailMatcher.matches()) {
                errors.put("submitterEmail", "Invalid email format");
            }
        }

        if (errors.isEmpty()) {
            response.put("status", "valid");
            response.put("documentRef", request.getDocumentRef());
            return ResponseEntity.ok(response);
        } else {
            response.put("status", "invalid");
            response.put("errors", errors);
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(response);
        }
    }

    @GetMapping("/search")
    public ResponseEntity<Map<String, Object>> searchDocuments(
            @RequestParam("q") String query,
            @RequestParam(value = "refFilter", required = false) String refFilter) {

        Map<String, Object> response = new HashMap<>();

        // Validate the reference filter if provided
        if (refFilter != null && !refFilter.isEmpty()) {
            Matcher filterMatcher = DOC_REFERENCE_PATTERN.matcher(refFilter);
            if (!filterMatcher.matches()) {
                response.put("error", "Invalid reference filter");
                return ResponseEntity.badRequest().body(response);
            }
        }

        // Simulated search results
        response.put("query", query);
        response.put("results", new Object[]{});
        return ResponseEntity.ok(response);
    }

    public static void main(String[] args) {
        SpringApplication.run(DocumentValidationService.class, args);
    }
}

class DocumentRequest {
    private String documentRef;
    private String comment;
    private String submitterEmail;

    public String getDocumentRef() { return documentRef; }
    public void setDocumentRef(String documentRef) { this.documentRef = documentRef; }
    public String getComment() { return comment; }
    public void setComment(String comment) { this.comment = comment; }
    public String getSubmitterEmail() { return submitterEmail; }
    public void setSubmitterEmail(String submitterEmail) { this.submitterEmail = submitterEmail; }
}
